# The files were previously rewritten to append `SEED_DATA_EXTRA` containing short translations.
# We will use simple string replacement to replace those blocks in the seed scripts.
# We will read the content, find `"name_te"` and slice out everything after it, then append the detailed translations.

def update_seed_file_detailed(peetha):
    filepath = rf"c:\Users\Bhoja\.gemini\antigravity-ide\scratch\panchapeetas\peethas\management\commands\seed_{peetha}.py"
    with io.open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find where the previously injected Telugu part starts
    index = content.find('"name_te":')
    if index != -1:
        # We will keep everything before "name_te"
        new_content = content[:index] + SEED_DATA_DETAILED[peetha] + "\n}"
        with io.open(filepath, 'w', encoding='utf-8') as f:
            f.write(new_content)
        print(f"Updated {filepath} with detailed translations")
    else:
        print(f"Could not find existing 'name_te' in {filepath}")

for peetha in SEED_DATA_DETAILED.keys():
    update_seed_file_detailed(peetha)
